-- Catálogo de procedimentos pedidos no atendimento (raio X, laboratório, exames,
-- medicação, eletivos): tabela rxprocedimentos.
--
-- Nenhuma migration cria nem popula esta tabela; ela vem do banco legado.
-- Use em banco NOVO montado sem cópia de dados. É seguro rodar em banco que já tem
-- a tabela: não altera nem apaga itens existentes (ON CONFLICT DO NOTHING) e pode
-- ser executado mais de uma vez.
--
-- Textos preservados como estão no banco (algumas descrições têm quebra de linha).
-- Gerado em 22/11/2026 a partir do banco de homologação (834 itens).
-- Uso: psql -h <host> -U <usuario> -d <banco> -v ON_ERROR_STOP=1 -f rxprocedimentos.sql

BEGIN;

CREATE SEQUENCE IF NOT EXISTS public.rxprocedimentos_idrx_seq AS integer START WITH 1 INCREMENT BY 1;

CREATE TABLE IF NOT EXISTS public.rxprocedimentos (
    idrx integer NOT NULL DEFAULT nextval('public.rxprocedimentos_idrx_seq'::regclass),
    codprocedimento character varying(15),
    descricao character varying(120),
    modo character varying(30),
    cid character varying(4),
    modo2 character varying(15),
    CONSTRAINT rxprocedimentos_pkey PRIMARY KEY (idrx)
);

ALTER SEQUENCE public.rxprocedimentos_idrx_seq OWNED BY public.rxprocedimentos.idrx;

', 'RAIO X', '0000', NULL) ON CONFLICT DO NOTHING;
)', 'LABORATORIO', '0000', 'ENFERMAGEM') ON CONFLICT DO NOTHING;
 ', 'FISIO', '0000', NULL) ON CONFLICT DO NOTHING;
', 'MEDICACAO', '0000', NULL) ON CONFLICT DO NOTHING;
', 'PROCEDIMENTO', '0000', NULL) ON CONFLICT DO NOTHING;
 ', 'FONO', '0000', NULL) ON CONFLICT DO NOTHING;
', 'MEDICACAO2', '0000', NULL) ON CONFLICT DO NOTHING;
', 'MEDICACAO3', '0000', NULL) ON CONFLICT DO NOTHING;

-- Próximo item cadastrado pela tela não pode colidir com os ids carregados.
SELECT setval('public.rxprocedimentos_idrx_seq',
              GREATEST((SELECT COALESCE(MAX(idrx), 1) FROM public.rxprocedimentos),
                       (SELECT last_value FROM public.rxprocedimentos_idrx_seq)));

COMMIT;
